bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
echo VIDEOBOT_RUNNING=YES
docker exec "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
const env=process.env;
console.log('VIDEO_TOPIC_CONFIG_PRESENT='+Boolean(env.VIDEOBOT_VIDEO_SALE_THREAD_ID));
console.log('VIDEO_TOPIC_TITLE_CONFIG_PRESENT='+Boolean(env.VIDEOBOT_VIDEO_SALE_TOPIC_TITLE));
const owner=readFileSync('/opt/videobot/owner/gateOwner.mjs','utf8');
console.log('VIDEO_PROVIDER_STUB='+owner.includes('VIDEO_TOPIC_NOT_CONNECTED'));
const w=readFileSync('/opt/videobot/src/telegram/creatorWiring.mjs','utf8');
console.log('VIDEO_WIRING_OLD_REVIEW_GATE='+w.includes('verifyReview:gateOwner.verifyReview'));
const p=readFileSync('/opt/videobot/src/telegram/paidListingPublisher.mjs','utf8');
console.log('VIDEO_PUBLISHER_OLD_REVIEW_GATE='+p.includes('listing review not approved'));
NODE
docker exec "$cid" node --input-type=module <<'NODE'
import pg from 'pg';import {readFileSync} from 'node:fs';
const env=process.env;
let url=env.VIDEOBOT_DATABASE_URL_FILE?readFileSync(env.VIDEOBOT_DATABASE_URL_FILE,'utf8').trim():null;
if(!url){
 const pass=readFileSync(env.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim();
 url='postgresql://'+encodeURIComponent(env.VIDEOBOT_DB_USER)+':'+encodeURIComponent(pass)+'@'+env.VIDEOBOT_DB_HOST+':5432/'+env.VIDEOBOT_DB_NAME;
}
const c=new pg.Client({connectionString:url,connectionTimeoutMillis:3000});
try{
 await c.connect();
 const rows=await c.query("SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_name IN ('videobot_listings','videobot_post_receipts','videobot_video_listings')");
 console.log('VIDEO_TABLE_NAMES='+rows.rows.map(x=>x.table_name).join(','));
 const cols=await c.query("SELECT table_name,column_name FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('videobot_listings','videobot_post_receipts','videobot_video_listings') ORDER BY table_name,ordinal_position");
 for(const table of [...new Set(cols.rows.map(x=>x.table_name))])console.log('COLUMNS_'+table+'='+cols.rows.filter(x=>x.table_name===table).map(x=>x.column_name).join(','));
}catch(e){console.log('VIDEO_DB_CHECK_ERROR_CODE='+(e.code||'UNKNOWN'));process.exitCode=76}
finally{await c.end().catch(()=>{})}
NODE
